export const marbleHeroFrag = "// marble-hero.frag — verde marble with brass veining (landing hero + workspace shell)\n// Domain-warped fBm gives slow-drifting stone; thin sharp ridges become brass veins.\n// Uniforms: uTime, uResolution, uMouse (built-in via ShaderCanvas)\n//           uBase (vec3 deep base), uMid (vec3 lighter stone), uVein (vec3 brass), uIntensity (float 0..1)\nprecision highp float;\n\nvarying vec2 vUv;\nuniform float uTime;\nuniform vec2 uResolution;\nuniform vec2 uMouse;\nuniform vec3 uBase;\nuniform vec3 uMid;\nuniform vec3 uVein;\nuniform float uIntensity;\n\nfloat hash(vec2 p) {\n  p = fract(p * vec2(123.34, 456.21));\n  p += dot(p, p + 45.32);\n  return fract(p.x * p.y);\n}\n\nfloat noise(vec2 p) {\n  vec2 i = floor(p);\n  vec2 f = fract(p);\n  float a = hash(i);\n  float b = hash(i + vec2(1.0, 0.0));\n  float c = hash(i + vec2(0.0, 1.0));\n  float d = hash(i + vec2(1.0, 1.0));\n  vec2 u = f * f * (3.0 - 2.0 * f);\n  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;\n}\n\nfloat fbm(vec2 p) {\n  float v = 0.0;\n  float a = 0.5;\n  mat2 m = mat2(1.6, 1.2, -1.2, 1.6);\n  for (int i = 0; i < 5; i++) {\n    v += a * noise(p);\n    p = m * p;\n    a *= 0.5;\n  }\n  return v;\n}\n\nvoid main() {\n  vec2 uv = vUv;\n  float aspect = uResolution.x / max(uResolution.y, 1.0);\n  vec2 p = (uv - 0.5) * vec2(aspect, 1.0) * 2.2;\n\n  float t = uTime * 0.035;                 // very slow drift\n  vec2 m = (uMouse - 0.5) * 0.30;          // gentle pointer parallax\n\n  // Two-level domain warp (Inigo Quilez style) for stone-like flow\n  vec2 q = vec2(fbm(p + t), fbm(p + vec2(5.2, 1.3) - t));\n  vec2 r = vec2(fbm(p + 3.0 * q + vec2(1.7, 9.2) + t * 1.5),\n                fbm(p + 3.0 * q + vec2(8.3, 2.8) - t));\n  float f = fbm(p + 3.5 * r + m);\n\n  // Veins: thin, sharp ridges from a warped sine field\n  float v1 = abs(sin((p.x * 0.9 + p.y * 0.6 + f * 6.0 + r.x * 2.0) * 2.51327));\n  v1 = pow(1.0 - v1, 9.0);\n  float v2 = abs(sin((p.y * 1.3 - p.x * 0.4 + r.y * 5.0) * 2.4));\n  v2 = pow(1.0 - v2, 16.0);\n\n  vec3 col = mix(uBase, uMid, smoothstep(0.18, 0.92, f));\n  col += uVein * (v1 * 0.55 + v2 * 0.30) * uIntensity;\n\n  // Soft brass light following the pointer\n  float spot = smoothstep(0.65, 0.0, length(uv - uMouse));\n  col += uVein * 0.05 * spot * uIntensity;\n\n  // Vignette keeps edges calm so UI sits on top\n  float vg = smoothstep(1.3, 0.2, length(uv - 0.5) * 1.45);\n  col *= mix(0.55, 1.0, vg);\n\n  gl_FragColor = vec4(col, 1.0);\n}\n";

export const paperGrainFrag = "// paper-grain.frag — ultra-light film/paper grain overlay (fixed, pointer-events:none).\n// Transparent, premultiplied. Updates ~12 times per second so it feels like tooth, not noise.\n// Uniforms: uAmount (0..0.12, default 0.05), uTime\nprecision mediump float;\n\nvarying vec2 vUv;\nuniform float uTime;\nuniform float uAmount;\n\nfloat hash(vec2 p) {\n  p = fract(p * vec2(443.897, 441.423));\n  p += dot(p, p.yx + 19.19);\n  return fract((p.x + p.y) * p.x);\n}\n\nvoid main() {\n  float n = hash(gl_FragCoord.xy + floor(uTime * 12.0) * 17.0);\n  float a = (n - 0.5) * 2.0 * uAmount;               // -uAmount .. +uAmount\n  vec3 c = a > 0.0 ? vec3(1.0) : vec3(0.0);\n  float alpha = abs(a);\n  gl_FragColor = vec4(c * alpha, alpha);             // premultiplied\n}\n";

export const riskAuraFrag = "// risk-aura.frag — soft, slowly pulsing glow behind the *selected* IndexTab.\n// Small canvas (~96x96). One instance at a time. Transparent (premultiplied alpha).\n// Uniforms: uColor (vec3 risk colour), uIntensity (0..1), uTime, uResolution\nprecision mediump float;\n\nvarying vec2 vUv;\nuniform float uTime;\nuniform vec2 uResolution;\nuniform vec3 uColor;\nuniform float uIntensity;\n\nvoid main() {\n  vec2 p = vUv - 0.5;\n  p.x *= uResolution.x / max(uResolution.y, 1.0);\n\n  float ang = atan(p.y, p.x);\n  float t = uTime * 0.7;\n  // Organic, non-circular edge\n  float wob = 0.05 * sin(ang * 3.0 + t) + 0.03 * sin(ang * 5.0 - t * 1.3);\n  float d = length(p) - (0.20 + wob);\n\n  float pulse = 0.85 + 0.15 * sin(uTime * 1.6);\n  float glow = exp(-max(d, 0.0) * 9.0) * 0.75;      // outer falloff\n  float core = smoothstep(0.0, -0.22, d) * 0.22;    // soft inner body\n  float a = clamp((glow + core) * pulse * uIntensity, 0.0, 1.0);\n\n  gl_FragColor = vec4(uColor * a, a);               // premultiplied\n}\n";

export const scanBeamFrag = "// scan-beam.frag — brass scan beam sweeping down the paper sheet during analysis.\n// Transparent overlay (premultiplied alpha). Use with <ShaderCanvas transparent />.\n// Uniforms: uProgress (0..1, top→bottom; drive from real streaming progress), uColor (vec3), uTime, uResolution\nprecision highp float;\n\nvarying vec2 vUv;\nuniform float uTime;\nuniform float uProgress;\nuniform vec2 uResolution;\nuniform vec3 uColor;\n\nfloat hash(vec2 p) {\n  p = fract(p * vec2(123.34, 456.21));\n  p += dot(p, p + 45.32);\n  return fract(p.x * p.y);\n}\n\nvoid main() {\n  float y = 1.0 - vUv.y;                     // 0 at top, 1 at bottom\n  float d = y - uProgress;\n\n  // Beam core + halo, slightly breathing\n  float breathe = 0.92 + 0.08 * sin(uTime * 6.0);\n  float beam = exp(-abs(d) * 110.0) * breathe;\n  float halo = exp(-abs(d) * 14.0) * 0.22;\n\n  // Already-scanned region: faint \"text rows\" that fade away from the beam\n  float behind = step(y, uProgress);\n  float fade = 1.0 - smoothstep(0.0, 0.32, uProgress - y);\n  float rowH = 14.0;\n  float row = step(0.58, fract(y * uResolution.y / rowH));\n  float col = step(0.18, hash(vec2(floor(vUv.x * uResolution.x / 9.0), floor(y * uResolution.y / rowH))));\n  float rows = row * col * behind * fade * 0.16;\n\n  float a = clamp(beam + halo + rows, 0.0, 1.0);\n  vec3 c = uColor * (0.85 + 0.35 * beam);\n  gl_FragColor = vec4(c * a, a);              // premultiplied\n}\n";

